#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    // The original program works with at most 8 vertices.
    const int MAXV = 8;
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 1;
    }
    int n = strtol(argv[1], NULL, 10);
    int m = strtol(argv[2], NULL, 10);
    // Validate the basic parameters (the original binary checks n,m < 8 and >=0).
    if (n < 0 || n > MAXV-1 || m < 0 || m > MAXV-1) {
        puts("INVALID_INPUT");
        return 1;
    }
    // Expect exactly 2*m additional arguments (u v pairs).
    if (argc != 3 + 2 * m) {
        puts("INVALID_INPUT");
        return 1;
    }
    int adj[MAXV][MAXV];
    memset(adj, 0, sizeof(adj));
    for (int i = 0; i < m; ++i) {
        int u = strtol(argv[3 + 2 * i], NULL, 10);
        int v = strtol(argv[3 + 2 * i + 1], NULL, 10);
        if (u < 0 || u >= n || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        adj[u][v] = 1;
        adj[v][u] = 1;
    }
    int visited[MAXV] = {0};
    int queue[MAXV];
    int component_index = 0;
    for (int start = 0; start < n; ++start) {
        if (visited[start]) continue;
        // BFS to collect the component.
        int head = 0, tail = 0;
        queue[tail++] = start;
        visited[start] = 1;
        int component_vertices[MAXV];
        int comp_sz = 0;
        while (head < tail) {
            int v = queue[head++];
            component_vertices[comp_sz++] = v;
            for (int w = 0; w < n; ++w) {
                if (adj[v][w] && !visited[w]) {
                    visited[w] = 1;
                    queue[tail++] = w;
                }
            }
        }
        // Output in the format observed in the original binary.
        printf("%d:", component_index);
        printf(" {");
        for (int i = 0; i < comp_sz; ++i) {
            printf("%d", component_vertices[i]);
            if (i + 1 < comp_sz) putchar(',');
        }
        putchar('}');
        putchar('\n');
        ++component_index;
    }
    return 0;
}
